<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { Api } from './lib/api';
  import type { AiSettings, AiConfig, AiTest, Snapshot } from './lib/api';
  import { aiPatch } from './lib/ai';
  import type { KeyChange } from './lib/ai';
  export let api: Api;
  export let snapshot: Snapshot;
  let saved: AiSettings | null = null, config: AiConfig | null = null;
  let loading = true, busy = false, testing = false, modelsBusy = false, error = '', success = '', modelsError = '';
  let layaKey: KeyChange = { mode: 'keep', value: '' }, llmKey: KeyChange = { mode: 'keep', value: '' };
  let models: string[] = [], sample = '', result: AiTest | null = null;
  let pending: ReturnType<typeof aiPatch> | null = null;
  let alive = true;
  function fail(cause: unknown) { return cause instanceof Error ? cause.message : 'The request failed.'; }
  function receive(value: AiSettings) { saved = value; config = { ...structuredClone(value.config), timeout_minutes: value.config.timeout_minutes || 10 }; layaKey = { mode: 'keep', value: '' }; llmKey = { mode: 'keep', value: '' }; }
  async function refresh() { loading = true; error = ''; try { const value = await api.request<AiSettings>('/ai/settings'); if (alive) receive(value); } catch (cause) { if (alive) error = fail(cause); } finally { if (alive) loading = false; } }
  async function status() { try { const value = await api.request<AiSettings>('/ai/settings'); if (alive && saved) saved = { ...saved, status: value.status }; } catch (cause) { if (alive) error = fail(cause); } }
  function prepare(event: SubmitEvent) { event.preventDefault(); if (!config || busy) return; pending = aiPatch(config, layaKey, llmKey); error = ''; success = ''; }
  async function save() { if (!pending || busy) return; busy = true; error = ''; try { const value = await api.request<AiSettings>('/ai/settings', 'PATCH', pending); if (alive) { receive(value); pending = null; success = 'AI settings saved.'; result = null; } } catch (cause) { if (alive) error = fail(cause); } finally { if (alive) busy = false; } }
  async function loadModels() { modelsBusy = true; modelsError = ''; try { const value = await api.request<{ models: string[] }>('/ai/models'); if (alive) models = [...value.models].sort((a, b) => Number(b.startsWith('gemma-')) - Number(a.startsWith('gemma-')) || a.localeCompare(b)); } catch (cause) { if (alive) modelsError = fail(cause); } finally { if (alive) modelsBusy = false; } }
  async function test(event: SubmitEvent) { event.preventDefault(); if (testing) return; testing = true; result = null; error = ''; try { const value = await api.request<AiTest>('/ai/test', 'POST', { content: sample }); if (alive) { result = value; await status(); } } catch (cause) { if (alive) error = fail(cause); } finally { if (alive) testing = false; } }
  onMount(() => { void refresh(); });
  onDestroy(() => { alive = false; layaKey.value = ''; llmKey.value = ''; pending = null; });
</script>

<p class="muted small">Owner only. New and edited messages are checked in the background; checks can take seconds or longer. The owner’s messages are exempt.</p>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if success}<p class="notice" role="status">{success}</p>{/if}
{#if loading}<p role="status">Loading AI settings…</p>{:else if config && saved}
  <section class="ai-status" aria-label="AI service status"><h3>Service status</h3><p>{saved.status.queued} queued · {saved.status.checked} checked · {saved.status.flagged} flagged · {saved.status.llm_requests_today} LLM requests today</p>{#if saved.status.last_error}<div class="error" role="alert"><strong>Last AI service error</strong><p>{saved.status.last_error}</p><p>Check the service address and that it is running on the host. This is the last recorded error since the host started. If the service is still unavailable, messages may remain unchecked.</p></div>{/if}<button class="secondary" disabled={busy || testing} onclick={status}>Refresh status</button></section>
  <form onsubmit={prepare}>
    <fieldset disabled={busy || !!pending}>
      <label class="check-label"><input type="checkbox" bind:checked={config.enabled}/>Enable AI moderation</label>
      <h3 class="section-heading">Covered text channels</h3><p class="muted small">Leave every channel unchecked to cover all text channels, including new ones.</p>
      <div class="permission-grid">{#each snapshot.channels.filter(channel => channel.type === 'text') as channel}<label class="check-label"><input type="checkbox" checked={config.channel_ids.includes(channel.id)} onchange={event => config!.channel_ids = event.currentTarget.checked ? [...config!.channel_ids, channel.id] : config!.channel_ids.filter(id => id !== channel.id)}/>#{channel.name}</label>{/each}</div>
      <label>When a message is flagged<select bind:value={config.action}><option value="flag">Send to review queue</option><option value="hide">Hide message automatically</option><option value="timeout">Time out author automatically</option></select></label>
      {#if config.action !== 'flag'}<p class="notice">This acts without human approval. {config.action === 'hide' ? 'The message is deleted and a copy kept in the review queue.' : 'The author is timed out and the message added to the review queue.'}</p>{/if}
      {#if config.action === 'timeout'}<label>Timeout duration (minutes)<input type="number" min="1" max="40320" step="1" required bind:value={config.timeout_minutes}/></label>{/if}
      <h3 class="section-heading">Laya local classifier</h3><p class="muted small">Install and run Laya on the host computer first. The address is reached by the host, not your browser. This screen does not download models.</p>
      <label class="check-label"><input type="checkbox" checked={!!config.laya} onchange={event => config!.laya = event.currentTarget.checked ? structuredClone(saved!.config.laya ?? { url: 'http://127.0.0.1:8000', has_api_key: false, threshold: 0.7, spam_threshold: 0.95 }) : null}/>Use Laya</label>
      {#if config.laya}<label>Laya service URL<input type="url" required bind:value={config.laya.url}/></label><div class="form-grid"><label>Toxicity / harassment / threat threshold<input type="number" min="0.05" max="1" step="0.01" required bind:value={config.laya.threshold}/></label><label>Spam threshold<input type="number" min="0.05" max="1" step="0.01" required bind:value={config.laya.spam_threshold}/></label></div><p class="muted small">Scores run from 0 to 1. Spam scores can be noisy; the default is 0.95.</p><label>Laya API key ({config.laya.has_api_key ? 'saved' : 'not saved'})<select bind:value={layaKey.mode}><option value="keep">Keep existing key</option><option value="replace">Set a new key</option><option value="remove">Remove saved key</option></select></label>{#if layaKey.mode === 'replace'}<label>New Laya key<input type="password" autocomplete="new-password" bind:value={layaKey.value} required/></label>{/if}{/if}
      <h3 class="section-heading">Language model</h3>
      <label class="check-label"><input type="checkbox" checked={!!config.llm} onchange={event => config!.llm = event.currentTarget.checked ? { kind: 'gemini', base_url: '', has_api_key: false, model: '', requests_per_minute: 30, requests_per_day: 14400, cloud: true } : null}/>Use a language model</label>
      {#if config.llm}<label>Provider<select bind:value={config.llm.kind}><option value="gemini">Google Gemini / Gemma</option><option value="openai">OpenAI-compatible service</option></select></label>
        {#if config.llm.kind === 'openai'}<label>API base URL<input type="url" required placeholder="http://127.0.0.1:11434/v1" bind:value={config.llm.base_url}/></label>{/if}
        <p class="notice">{config.llm.kind === 'gemini' ? 'Messages will be sent to Google’s outside AI service.' : 'Messages are sent to this endpoint. An endpoint outside the host or LAN is treated as a cloud service.'} Members see a notice in covered channels.</p>
        <label>Model ID<input required bind:value={config.llm.model} list="ai-model-suggestions" placeholder="Choose a model or enter its exact ID"/></label><datalist id="ai-model-suggestions">{#each models as model}<option value={model}></option>{/each}</datalist><button type="button" class="secondary" disabled={modelsBusy || !saved.config.llm} onclick={loadModels}>{modelsBusy ? 'Loading models…' : 'Load saved provider’s models'}</button><p class="small muted">Save provider settings first. Model IDs can always be entered manually; Gemma models appear first in suggestions.</p>{#if modelsError}<p class="error" role="alert">{modelsError}</p>{/if}
        <label>LLM API key ({config.llm.has_api_key ? 'saved' : 'not saved'})<select bind:value={llmKey.mode}><option value="keep">Keep existing key</option><option value="replace">Set a new key</option><option value="remove">Remove saved key</option></select></label>{#if llmKey.mode === 'replace'}<label>New LLM key<input type="password" autocomplete="new-password" bind:value={llmKey.value} required/></label>{/if}
        <div class="form-grid"><label>Requests per minute<input type="number" min="1" max="10000" step="1" required bind:value={config.llm.requests_per_minute}/></label><label>Requests per day<input type="number" min="1" max="10000000" step="1" required bind:value={config.llm.requests_per_day}/></label></div>
      {/if}
      <label>Extra moderation rules<textarea maxlength="2000" bind:value={config.rules} placeholder="Describe what the language model should flag."></textarea></label>
      <p class="small muted">With both providers enabled, the LLM confirms Laya flags. If the LLM fails or hits its limit, Laya’s verdict becomes a review flag rather than an automatic action.</p>
      <button class="primary" disabled={config.enabled && !config.laya && !config.llm}>Review changes</button>
    </fieldset>
  </form>
  {#if pending}<div class="confirm-box" role="alert"><h3>Apply AI moderation settings?</h3><p>{pending.enabled ? 'AI checking will be enabled for the selected channels.' : 'AI checking will be turned off.'} Action: {pending.action === 'flag' ? 'human review' : pending.action === 'hide' ? 'delete flagged messages automatically' : 'time out authors automatically'}.</p>{#if pending.enabled && pending.llm}<p>Messages in covered channels may be read by the configured outside service. Members will receive the server’s disclosure notice.</p>{/if}<div class="button-row"><button class="secondary" disabled={busy} onclick={() => pending = null}>Cancel</button><button class="primary" disabled={busy} onclick={save}>{busy ? 'Saving…' : 'Confirm AI settings'}</button></div></div>{/if}
  <h3 class="section-heading">Try saved configuration</h3><p class="small muted">A sample is checked without storing it, deleting messages or timing anyone out. Save settings above first. CPU checks can take a minute; you can keep chatting while checks run.</p>
  {#if saved.config.llm}<p class="notice">The sample is sent through the saved provider configuration. {saved.notice?.cloud || saved.config.llm.cloud || saved.config.llm.kind === 'gemini' ? 'It may be read by an outside AI service.' : 'The configured service runs on the host or LAN.'}</p>{/if}
  <form onsubmit={test}><label>Sample message<textarea bind:value={sample} required maxlength="4000" disabled={testing}></textarea></label><button class="secondary" disabled={testing || busy || (!saved.config.laya && !saved.config.llm)}>{testing ? 'Checking in background…' : 'Send sample for AI check'}</button></form>
  {#if result}<section class="ai-test-result" aria-label="AI test result"><h4>{result.error ? 'Check failed or incomplete' : result.verdict.flagged ? 'Flagged for moderation' : 'No flag returned'}</h4>{#if result.error}<p class="error" role="alert">{result.error}</p>{/if}<p>{result.verdict.reason}</p><p class="small muted">{result.verdict.provider} · {(result.ms / 1000).toFixed(1)} seconds · Suggested action: {result.action}</p>{#if result.verdict.unconfirmed}<p class="notice">The language model did not confirm this result. Automatic actions are downgraded to a review flag.</p>{/if}<p>{result.verdict.categories.join(', ')}</p>{#if result.verdict.scores}<dl class="ai-scores">{#each Object.entries(result.verdict.scores) as [name, score]}<div><dt>{name}</dt><dd>{score.toFixed(3)}</dd></div>{/each}</dl>{/if}</section>{/if}
{/if}
